comments.body:
note: it seems like `string-literal-with-embedded-nul` only checks `std::string` constructors, not `std::string_view`. Similar `ToLower` (:1156) and `ToUpper` (:1170) tests have the same bug and don't get flagged. For example, the below diff passes the test.

<details>
<summary>git diff on fa60b2ae8d</summary>

```diff
diff --git a/src/test/util_tests.cpp b/src/test/util_tests.cpp
index 6db2f90908..f3cdec9063 100644
--- a/src/test/util_tests.cpp
+++ b/src/test/util_tests.cpp
@@ -1153,7 +1153,7 @@ BOOST_AUTO_TEST_CASE(test_ToLower)

     BOOST_CHECK_EQUAL(ToLower(""), "");
     BOOST_CHECK_EQUAL(ToLower("#HODL"), "#hodl");
-    BOOST_CHECK_EQUAL(ToLower("\x00\xfe\xff"), "\x00\xfe\xff");
+    BOOST_CHECK_EQUAL(ToLower("\x00\xfe\xff"), "");
 }

 BOOST_AUTO_TEST_CASE(test_ToUpper)
@@ -1167,7 +1167,7 @@ BOOST_AUTO_TEST_CASE(test_ToUpper)

     BOOST_CHECK_EQUAL(ToUpper(""), "");
     BOOST_CHECK_EQUAL(ToUpper("#hodl"), "#HODL");
-    BOOST_CHECK_EQUAL(ToUpper("\x00\xfe\xff"), "\x00\xfe\xff");
+    BOOST_CHECK_EQUAL(ToUpper("\x00\xfe\xff"), "");
 }

 BOOST_AUTO_TEST_CASE(test_Capitalize)

```
</details>
